<script setup>
import { ref, watch, onBeforeUnmount } from 'vue';
import { ccCore } from '../../api/cc-core';
import CCJourneyChips from './CCJourneyChips.vue';
const props=defineProps({lead:Object});
const timelineMore=ref(false),timelineCapped=ref(false);
const summary=ref(null),header=ref(null),events=ref([]),matches=ref(null),number=ref(''),error=ref(''),busy=ref(false),expanded=ref(false),matching=ref(false);
const emit=defineEmits(['changed','summary','header']);let generation=0;
watch(()=>props.lead?.name,async()=>{const token=++generation;summary.value=null;header.value=null;events.value=[];matches.value=null;expanded.value=false;matching.value=false;error.value='';try{const data=await ccCore('header',{lead:props.lead.name});if(token!==generation)return;header.value=data;summary.value=data.summary;emit('header',data);emit('summary',data.summary);}catch(e){if(token===generation)error.value=e.message;}},{immediate:true});
onBeforeUnmount(()=>generation++);
async function action(kind,args={}){busy.value=true;error.value='';const token=generation;try{const data=await ccCore(kind,{lead:props.lead.name,...args});if(token!==generation)return;if(data.summary){summary.value=data.summary;emit('summary',data.summary);}if(kind==='timeline'){events.value=args.start?[...events.value,...(data.events||[])]:data.events||[];timelineMore.value=!!data.more;timelineCapped.value=!!data.capped;expanded.value=true;}if(kind==='match'){matches.value=data;matching.value=true;}if(kind==='add_number'){emit('changed',data.modified);number.value='';await action('match');}if(kind==='match_verify'){await action('match');}}catch(e){if(token===generation)error.value=e.message;}finally{busy.value=false;}}
</script>
<template>
<section class="card cc-journey" aria-label="Lead journey"><header class="card-hdr">Lead journey <button class="btn btn-gy btn-sm" :disabled="busy" @click="action('timeline')">Timeline</button><button class="btn btn-gy btn-sm" :disabled="busy" @click="action('match')">Match branch client</button></header><div class="card-body">
<CCJourneyChips :summary="summary"/><div v-if="summary" class="cc-journey-grid"><div><small>Milestone</small><strong>{{summary.milestone}}</strong><span>Booked {{summary.booked}} · Missed {{summary.missed}} · Visited {{summary.visited}}</span></div><div><small>Last call</small><strong>{{summary.last_call_result||'No call yet'}}</strong><span>{{summary.last_call_at}}</span></div><div><small>Next action</small><strong>{{summary.next_action}}</strong><span>{{summary.next_action_due||'No date set'}}</span></div></div>
<div v-if="header" class="cc-lead-received"><span>Received {{header.received_this||'—'}}</span><span v-if="header.received_first&&header.received_first!==header.received_this">First enquiry {{header.received_first}}</span><strong v-if="header.visit">{{header.visit.code}} – {{header.visit.by||'Consultant pending'}} · {{header.visit.on}}</strong></div><div v-if="header" class="cc-note">Owner {{header.owner||'—'}} · Last touch {{header.last_touch||'—'}} <span v-if="header.last_touch_by">by {{header.last_touch_by}}</span></div>
<p v-if="error" role="alert" class="cc-error">{{error}}</p><p v-if="busy" role="status">Loading…</p>
<div v-if="expanded" class="tbl-wrap"><button class="btn btn-gy btn-sm" @click="expanded=false">Close timeline</button><table><thead><tr><th>When</th><th>Event</th><th>Result</th><th>By</th></tr></thead><tbody><tr v-for="(event,i) in events" :key="i"><td>{{event.at}}</td><td>{{event.kind}}</td><td>{{event.from}} → {{event.to}}</td><td>{{event.by}}</td></tr><tr v-if="!events.length"><td colspan="4">No activity recorded.</td></tr></tbody></table><button v-if="timelineMore" class="btn btn-gy btn-sm" :disabled="busy" @click="action('timeline',{start:events.length})">Load older history</button><p v-if="timelineCapped">This timeline reached its display limit. Narrow the call-history dates for older records.</p></div>
<div v-if="matching"><button class="btn btn-gy btn-sm" @click="matching=false">Close matches</button><form class="cc-journey-number" @submit.prevent="action('add_number',{number})"><label>Additional contact number <input v-model="number" inputmode="tel" pattern="[0-9]{10}" maxlength="10" required></label><button class="btn btn-g btn-sm" :disabled="busy">Add and check</button></form><article v-for="match in matches?.matches||[]" :key="match.patient" class="cc-match"><strong>{{match.name}} · {{match.patient}}</strong><p>{{match.branch}} · ••••{{match.mobile_last4}} · Paid ₹{{match.paid}} · {{match.status}}</p><template v-if="matches.can_verify"><button class="btn btn-g btn-sm" :disabled="busy" @click="action('match_verify',{patient:match.patient,decision:'Verified'})">Verify same client</button><button class="btn btn-gy btn-sm" :disabled="busy" @click="action('match_verify',{patient:match.patient,decision:'Rejected'})">Different client</button></template></article><p v-if="!matches?.matches?.length">No matching branch client found.</p></div>
</div></section>
</template>
<style scoped>.cc-journey{margin:12px 0}.cc-journey-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:8px 0}.cc-journey-grid>div{display:grid;gap:5px;background:#f5f7ef;border:1px solid #e3dccb;border-radius:8px;padding:12px}.cc-journey-grid small{color:#718075;text-transform:uppercase}.cc-journey-grid span{font-size:12px}.cc-journey-number{display:flex;align-items:end;gap:10px;margin:12px 0}.cc-journey-number label{display:grid;gap:6px}.cc-match{border-top:1px solid #e3dccb;padding:12px 0}@media(max-width:700px){.cc-journey-grid{grid-template-columns:1fr}.cc-journey-number{flex-wrap:wrap}}</style>
